function validate([n, rectangles]) {
  if (n < 3 || n > 1e9) return 'n is between 3 and 10^9.';
  if (rectangles.length < 3 || rectangles.length > 1e5) return 'rectangles needs 3 to 10^5 rectangles.';
  for (const r of rectangles) {
    if (r.length !== 4) return 'Each rectangle is [startX, startY, endX, endY].';
    if (r.some((v) => v < 0 || v > n)) return 'Every coordinate is between 0 and n.';
    if (r[0] >= r[2] || r[1] >= r[3]) return 'Each rectangle needs startX < endX and startY < endY.';
  }
  // Sweep across x: rectangles present at the same x must have disjoint y-ranges.
  const events = [];
  rectangles.forEach((r, i) => events.push([r[0], 1, i], [r[2], 0, i]));
  events.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const active = [];
  const position = (y) => {
    let lo = 0;
    let hi = active.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (active[mid][0] < y) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  };
  for (const [, open, i] of events) {
    const y1 = rectangles[i][1];
    const y2 = rectangles[i][3];
    const at = position(y1);
    if (!open) {
      active.splice(at, 1);
      continue;
    }
    if ((at > 0 && active[at - 1][1] > y1) || (at < active.length && active[at][0] < y2)) return 'No two rectangles may overlap.';
    active.splice(at, 0, [y1, y2]);
  }
  return null;
}

