function checkValidCuts(n, rectangles) {
  const countBlocks = (from, to) => {
    const spans = rectangles.map((rect) => [rect[from], rect[to]]);
    spans.sort((a, b) => a[0] - b[0]);
    let blocks = 0;
    let reach = 0;
    for (const [start, end] of spans) {
      if (start >= reach) {
        blocks++;
      }
      reach = Math.max(reach, end);
    }
    return blocks;
  };

  return countBlocks(0, 2) >= 3 || countBlocks(1, 3) >= 3;
}

