function checkValidCuts(n, rectangles) {
  // Try every pair of rectangle edges as the two lines on each axis and test the definition directly.
  for (const [lo, hi] of [[0, 2], [1, 3]]) {
    const lines = [...new Set(rectangles.flatMap((r) => [r[lo], r[hi]]))].sort((a, b) => a - b);
    for (const first of lines) {
      for (const second of lines) {
        if (first >= second) continue;
        const crossed = rectangles.some((r) => (r[lo] < first && first < r[hi]) || (r[lo] < second && second < r[hi]));
        if (crossed) continue;
        const below = rectangles.filter((r) => r[hi] <= first).length;
        const middle = rectangles.filter((r) => r[lo] >= first && r[hi] <= second).length;
        const above = rectangles.filter((r) => r[lo] >= second).length;
        if (below > 0 && middle > 0 && above > 0) return true;
      }
    }
  }
  return false;
}

