function generate(rand, size) {
  const large = size === 'large';
  const pick = (k) => Math.floor(rand() * k);
  const shuffle = (list) => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = pick(i + 1);
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  // Guillotine tiling: split regions in two along an axis until there are enough tiles.
  // With twoSlabs, the first cut is followed by cuts across it in both halves, which usually blocks every split.
  const tile = (n, target, twoSlabs) => {
    const regions = [[0, 0, n, n]];
    const split = (i, vertical) => {
      const [x1, y1, x2, y2] = regions[i];
      const low = vertical ? x1 : y1;
      const high = vertical ? x2 : y2;
      if (high - low < 2) return;
      const cut = low + 1 + pick(high - low - 1);
      regions[i] = vertical ? [x1, y1, cut, y2] : [x1, y1, x2, cut];
      regions.push(vertical ? [cut, y1, x2, y2] : [x1, cut, x2, y2]);
    };
    if (twoSlabs) {
      const vertical = rand() < 0.5;
      split(0, vertical);
      for (let i = regions.length - 1; i >= 0; i--) split(i, !vertical);
    }
    for (let tries = 0; regions.length < target && tries < 20 * target; tries++) split(pick(regions.length), rand() < 0.5);
    const keep = rand() < 0.5 ? 1 : 0.6 + 0.4 * rand();
    return regions.filter(() => rand() < keep);
  };
  for (;;) {
    const n = large ? 1000 + pick(999999001) : 3 + pick(6);
    let rects;
    if (large || rand() < 0.5) {
      rects = tile(n, large ? 1500 + pick(501) : 3 + pick(7), rand() < 0.5);
    } else {
      // Random placement: a new rectangle is kept only if it misses every earlier one.
      const target = 3 + pick(6);
      rects = [];
      for (let attempt = 0; attempt < 300 && rects.length < target; attempt++) {
        const w = 1 + pick(Math.min(n, 4));
        const h = 1 + pick(Math.min(n, 4));
        const x = pick(n - w + 1);
        const y = pick(n - h + 1);
        if (rects.every(([a, b, c, d]) => c <= x || x + w <= a || d <= y || y + h <= b)) rects.push([x, y, x + w, y + h]);
      }
    }
    if (rects.length >= 3 && rects.length <= 2000) return [n, shuffle(rects)];
  }
}
